def _category_generation_cache_key(category_key, headlines):
    sources = []
    for source in headlines or []:
        body = source.get("article_text", "") or source.get("summary", "")
        sources.append({
            "title": source.get("title", ""),
            "url": _normalize_cache_url(source.get("link", "")),
            "published": source.get("published", ""),
            "source_type": source.get("source_type", ""),
            "source_quality": source.get("source_quality", ""),
            "hero_eligible": source.get("hero_eligible", ""),
            "category_match_score": source.get("category_match_score", ""),
            "content_hash": hashlib.sha256(body.encode("utf-8")).hexdigest(),
        })
    return _cache_hash({
        "version": CATEGORY_GENERATION_PROMPT_VERSION,
        "model_articles": MODEL_ARTICLES,
        "model_selection": MODEL_SELECTION,
        "category_key": category_key,
        # Invalidate only the category whose explicit contract changed. Other beat
        # caches remain reusable because their generation policy is unchanged.
        "category_eligibility_contract_version": (
            CATEGORY_ELIGIBILITY_CONTRACT_VERSION if category_key == "local_gov" else ""
        ),
        "sources": sources,
    })

