def validate_product_guide_fidelity(item, page_html):
    if str(item.get("article_type") or "") != "product_guide":
        return True
    import html as _html
    page = str(page_html or "")
    missing = []
    disclosure = _html.escape(str(item.get("affiliate_disclosure") or DEFAULT_AFFILIATE_DISCLOSURE))
    if disclosure not in page:
        missing.append("affiliate_disclosure")
    for index, product in enumerate(item.get("products") or [], start=1):
        checks = {
            f"product_{index}_name": _html.escape(str(product.get("name") or "")),
            f"product_{index}_image": _html.escape(str(product.get("image_url") or ""), quote=True),
            f"product_{index}_affiliate_url": _html.escape(str(product.get("affiliate_url") or ""), quote=True),
        }
        for label, value in checks.items():
            if not value or value not in page:
                missing.append(label)
    if missing:
        raise RuntimeError(
            f"Product guide fidelity FAILED for '{item.get('headline','')[:60]}': "
            + ", ".join(missing[:10])
        )
    return True


def apply_custom_retirements_to_live(all_categories, top_cat=None, output_root=None):
    retired = _load_custom_retirements(output_root)
    if not retired:
        return 0
    removed = 0
    for category in all_categories or []:
        hero = category.get("hero")
        if hero and (hero.get("is_custom") or hero.get("authoritative_custom")) and _is_retired_custom_item(hero, output_root):
            cards = category.get("cards") or []
            category["hero"] = cards.pop(0) if cards else None
            category["cards"] = cards
            removed += 1
        kept = []
        for card in category.get("cards") or []:
            if (card.get("is_custom") or card.get("authoritative_custom")) and _is_retired_custom_item(card, output_root):
                removed += 1
                continue
            kept.append(card)
        category["cards"] = kept
    if isinstance(top_cat, dict):
        hero = top_cat.get("hero") or {}
        if (hero.get("is_custom") or hero.get("authoritative_custom")) and _is_retired_custom_item(hero, output_root):
            cards = top_cat.get("cards") or []
            top_cat["hero"] = cards.pop(0) if cards else None
            top_cat["cards"] = cards
            removed += 1
    if removed:
        print(f"  Retired custom content removed from {removed} live placement(s)")
    return removed


def _render_retired_custom_redirect_page(headline="", category_key=""):
    """Remove retired article content while preserving a noindex path handoff."""
    target_path = f"/{category_key}.html" if category_key in CATEGORIES else "/archive.html"
    target_url = f"{SITE_URL}{target_path}"
    safe_title = re.sub(r"[<>]", "", headline or "Removed article")
    return f'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{safe_title} | {SITE_NAME}</title>
  <link rel="canonical" href="{target_url}">
  <meta name="robots" content="noindex,nofollow">
  <meta http-equiv="refresh" content="0; url={target_url}">
  <script>window.location.replace({json.dumps(target_url)});</script>
</head>
<body>
  <p>This article has been removed. Continue to <a href="{target_url}">{SITE_NAME}</a>.</p>
</body>
</html>'''


def apply_custom_retirements_to_archive(output_root=None):
    root = Path(output_root or OUTPUT_DIR)
    retired = _load_custom_retirements(root)
    retired_slugs = _load_custom_retired_slugs(root)
    purge_slugs = _load_custom_purge_slugs(root)
    archive_path = root / "archive.json"
    if not (retired or retired_slugs) or not archive_path.exists():
        return 0
    archive = load_archive(archive_path)
    kept = []
    changed = 0
    purged = []
    articles_dir = root / "articles"
    for entry in archive:
        if not isinstance(entry, dict) or not (entry.get("is_custom") or entry.get("authoritative_custom")):
            kept.append(entry)
            continue
        entry_headline = _exact_custom_headline(entry.get("headline"))
        entry_slug = str(entry.get("slug") or "").strip()
        if entry_headline not in retired and entry_slug not in retired_slugs:
            kept.append(entry)
            continue
        if entry_slug in purge_slugs:
            purged.append({
                "headline": entry_headline,
                "slug": entry_slug,
                "category_key": str(entry.get("category_key") or ""),
            })
            articles_dir.mkdir(parents=True, exist_ok=True)
            (articles_dir / f"{entry_slug}.html").write_text(
                _render_retired_custom_redirect_page(
                    entry_headline, str(entry.get("category_key") or "")
                ),
                encoding="utf-8",
            )
            continue
        if not entry.get("exclude_from_live_recovery") or entry.get("identity_quarantine_reason") != "editor_retired_custom_article":
            changed += 1
        entry["retired_custom"] = True
        entry["ranking_eligible"] = False
        entry["exclude_from_live_recovery"] = True
        entry["identity_quarantine_reason"] = "editor_retired_custom_article"
        entry["legacy_identity_status"] = "editor_retired"
        kept.append(entry)

    if changed or purged:
        archive_path.write_text(json.dumps(kept, indent=2, ensure_ascii=False), encoding="utf-8")
        if changed:
            print(f"  Retired {changed} custom archive record(s) from live recovery")
    if purged:
        # Public discovery surfaces are derived from the post-retirement archive so a
        # purged custom URL cannot remain listed after its article content is removed.
        (root / "archive.html").write_text(render_archive_page(kept), encoding="utf-8")
        (root / "sitemap.xml").write_text(update_sitemap(kept), encoding="utf-8")
        (root / "news-sitemap.xml").write_text(update_news_sitemap(kept), encoding="utf-8")
        data_dir = root / "data"
        data_dir.mkdir(parents=True, exist_ok=True)
        (data_dir / "custom-retirement-report.json").write_text(json.dumps({
            "schema_version": 1,
            "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "quarantined_count": changed,
            "purged_count": len(purged),
            "purged": purged,
        }, indent=2, ensure_ascii=False), encoding="utf-8")
        print(f"  Purged {len(purged)} retired custom article(s) from public archive and discovery surfaces")
    return changed + len(purged)

def _declared_custom_category(item):
    """Return the normalized category explicitly assigned to a custom article."""
    if not isinstance(item, dict):
        return ""
    key = str(item.get("category") or item.get("category_key") or "").strip()
    return key if key in CATEGORIES else ""


def _custom_placement_identity(item):
    if not isinstance(item, dict):
        return ""
    return str(
        item.get("custom_body_hash")
        or item.get("editorial_story_id")
        or item.get("_editorial_story_id")
        or _custom_story_fingerprint(item.get("headline", ""), item.get("teaser", ""))
        or item.get("headline", "")
    )


def enforce_custom_category_placement(all_categories):
    """Keep authoritative custom content only in its declared category container.

    Permalink rebinding must never turn an unrelated category hero into a custom
    article merely because a legacy archive matcher found a broad topical overlap.
    This repair is deterministic and runs before hero selection.
    """
    all_categories = all_categories or []
    cat_by_key = {str(cat.get("category_key") or ""): cat for cat in all_categories}
    moves = []

    for cat in list(all_categories):
        container_key = str(cat.get("category_key") or "")
        hero = cat.get("hero")
        if hero and (hero.get("is_custom") or hero.get("authoritative_custom")):
            expected = _declared_custom_category(hero)
            if expected and expected != container_key:
                cat["hero"] = (cat.get("cards") or []).pop(0) if cat.get("cards") else None
                moves.append((hero, container_key, expected, "hero"))

        kept = []
        for card in cat.get("cards") or []:
            if card.get("is_custom") or card.get("authoritative_custom"):
                expected = _declared_custom_category(card)
                if expected and expected != container_key:
                    moves.append((card, container_key, expected, "card"))
                    continue
            kept.append(card)
        cat["cards"] = kept

    for item, source_key, expected, placement in moves:
        target = cat_by_key.get(expected)
        if target is None:
            target = {
                "category_key": expected,
                "category_label": CATEGORIES.get(expected, {}).get(
                    "label", expected.replace("_", " ").title()
                ),
                "hero": None,
                "cards": [],
            }
            all_categories.append(target)
            cat_by_key[expected] = target

        identity = _custom_placement_identity(item)
        target_items = [target.get("hero")] + list(target.get("cards") or [])
        if any(
            existing
            and (existing.get("is_custom") or existing.get("authoritative_custom"))
            and _custom_placement_identity(existing) == identity
            for existing in target_items
        ):
            continue

        if item.get("force_hero"):
            if target.get("hero"):
                target.setdefault("cards", []).insert(0, target["hero"])
            target["hero"] = item
        elif target.get("hero") is None:
            target["hero"] = item
        else:
            target.setdefault("cards", []).append(item)

        print(
            "  Custom category repair: "
            f"'{item.get('headline','')[:55]}' {source_key}:{placement} -> {expected}"
        )

    return {
        "moved": len(moves),
        "placements": [
            {
                "headline": item.get("headline", ""),
                "from_category": source,
                "to_category": expected,
                "placement": placement,
            }
            for item, source, expected, placement in moves
        ],
    }


def validate_custom_category_placement(all_categories, output_root=None):
    """Fail closed if a custom article remains outside its declared category."""
    violations = []
    checked = 0
    for cat in all_categories or []:
        container_key = str(cat.get("category_key") or "")
        for placement, item in [("hero", cat.get("hero"))] + [
            ("card", card) for card in cat.get("cards") or []
        ]:
            if not item or not (item.get("is_custom") or item.get("authoritative_custom")):
                continue
            checked += 1
            expected = _declared_custom_category(item)
            if expected and expected != container_key:
                violations.append({
                    "headline": item.get("headline", ""),
                    "placement": placement,
                    "container_category": container_key,
                    "declared_category": expected,
                })
    report = {
        "version": "1.10.5.2",
        "passed": not violations,
        "checked_custom_placements": checked,
        "violation_count": len(violations),
        "violations": violations,
    }
    if output_root is not None:
        path = Path(output_root) / "data" / "custom-category-contract.json"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
    if violations:
        raise RuntimeError(
            "Custom category contract FAILED: "
            + "; ".join(
                f"{row['headline'][:45]} ({row['container_category']} -> {row['declared_category']})"
                for row in violations[:5]
            )
        )
    return report


def load_custom_articles():
    """Load manual publications using an exact-headline-only update contract.

    The same headline updates the existing custom permalink and may replace the
    complete body, image, category or product data. Any headline difference creates a
    new article. No fuzzy, body-hash, recurring-series, source or story-ID matching is
    allowed to authorize a custom overwrite.
    """
    path = OUTPUT_DIR / "custom_articles.json"
    if not path.exists():
        return []
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            "custom_articles.json is invalid JSON at "
            f"line {exc.lineno}, column {exc.colno}: {exc.msg}. "
            "Generation stopped because silently dropping custom articles is not allowed."
        ) from exc
    except OSError as exc:
        raise RuntimeError(f"custom_articles.json could not be read: {exc}") from exc
    if not isinstance(data, list):
        raise RuntimeError(
            "custom_articles.json must contain a top-level JSON array. "
            "Generation stopped because silently dropping custom articles is not allowed."
        )

    from datetime import timezone as _tz
    now = datetime.now(_tz.utc)
    retired = _load_custom_retirements(OUTPUT_DIR)
    archive = load_archive(OUTPUT_DIR / "archive.json")
    archived_by_exact_headline = {}
    for existing in archive:
        if not isinstance(existing, dict) or not (existing.get("is_custom") or existing.get("authoritative_custom")):
            continue
        headline = _exact_custom_headline(existing.get("headline"))
        if not headline or headline in retired or existing.get("retired_custom"):
            continue
        archived_by_exact_headline.setdefault(headline, []).append(existing)
    for rows in archived_by_exact_headline.values():
        rows.sort(key=lambda row: (
            str(row.get("first_published") or row.get("date") or ""),
            str(row.get("slug") or ""),
        ))

    live = []
    skipped_published = 0
    retired_skips = 0
    queued_headlines = set()
    queued_slugs = {}
    for index, raw in enumerate(data, start=1):
        if not isinstance(raw, dict):
            raise RuntimeError(
                f"custom_articles.json item {index} must be a JSON object, "
                f"not {type(raw).__name__}."
            )
        art = dict(raw)
        headline = _exact_custom_headline(art.get("headline"))
        if not headline:
            raise RuntimeError(f"custom_articles.json item {index} is missing a non-empty headline.")
        if headline in queued_headlines:
            raise RuntimeError(
                f"custom_articles.json contains the exact headline more than once: '{headline}'. "
                "Keep one authoritative queue entry per headline."
            )
        queued_headlines.add(headline)
        requested_slug = _validated_custom_requested_slug(art.get("slug"))
        if requested_slug:
            prior_headline = queued_slugs.get(requested_slug)
            if prior_headline and prior_headline != headline:
                raise RuntimeError(
                    "custom_articles.json reuses slug "
                    f"'{requested_slug}' for both '{prior_headline}' and '{headline}'. "
                    "Each custom headline requires a unique requested slug."
                )
            queued_slugs[requested_slug] = headline
        if art.get("retired") is True or headline in retired:
            retired_skips += 1
            continue
        expires = str(art.get("expires") or "").strip()
        if expires:
            try:
                exp_dt = datetime.strptime(expires, "%Y-%m-%d").replace(tzinfo=_tz.utc)
                if now > exp_dt + timedelta(days=1):
                    continue
            except Exception:
                pass
        if not str(art.get("category") or "").strip():
            raise RuntimeError(
                f"Custom article '{headline}' is missing a category. "
                "Generation stopped before publication."
            )
        try:
            if str(art.get("article_type") or "") == "product_guide":
                _normalize_product_guide(art)
            elif not str(art.get("body") or "").strip():
                raise ValueError("missing non-empty body")
        except ValueError as exc:
            raise RuntimeError(f"Custom article '{headline}' invalid: {exc}") from exc

        art["headline"] = headline
        art["_custom_requested_slug"] = str(art.get("slug") or "").strip()
        art["_custom_requested_replace_slug"] = ""
        exact_matches = archived_by_exact_headline.get(headline, [])
        exact_existing = exact_matches[0] if exact_matches else None
        payload_hash = _custom_body_hash(art.get("body", ""))
        if exact_existing:
            saved_hash = str(exact_existing.get("custom_body_hash") or "")
            product_signature = str(exact_existing.get("product_guide_hash") or "")
            current_product_signature = _product_guide_hash(art) if str(art.get("article_type") or "") == "product_guide" else ""
            if not art.get("republish") and saved_hash and saved_hash == payload_hash and product_signature == current_product_signature:
                # An unchanged queue entry is still an ACTIVE editorial placement.
                # Removing it from this run forces archive recovery to reintroduce the
                # story as ``_archive_only``, which in turn makes a freshly published
                # original TCT article ineligible for front-page selection. Preserve
                # the established permalink and first-publication time, but mark the
                # payload as a no-op so write_archives does not rewrite it.
                slug = str(exact_existing.get("slug") or "")
                art["replace_slug"] = slug
                art["_custom_requested_replace_slug"] = slug
                art["_custom_exact_headline_update"] = True
                art["_custom_payload_unchanged"] = True
                art["_custom_active_queue"] = True
                art["_archived_slug"] = slug
                art["slug"] = slug or art.get("slug", "")
                if slug:
                    art["link"] = f"{SITE_URL}/articles/{slug}.html"
                for key in (
                    "first_published", "date", "lastmod", "published_raw",
                    "editorial_story_id", "ranking_eligible", "legacy_identity_status",
                ):
                    if exact_existing.get(key) not in (None, ""):
                        art[key] = exact_existing.get(key)
                skipped_published += 1
                print(f"  Custom active queue retained (payload unchanged): '{headline[:60]}'")
            else:
                art["replace_slug"] = exact_existing.get("slug", "")
                art["_custom_requested_replace_slug"] = exact_existing.get("slug", "")
                art["_custom_exact_headline_update"] = True
                art["_custom_active_queue"] = True
                print(f"  Custom exact-headline update queued: '{headline[:60]}'")
        else:
            art.pop("replace_slug", None)
            art.pop("update_existing", None)

        art["is_custom"] = True
        art["authoritative_custom"] = True
        art["_custom_active_queue"] = True
        art["custom_body_hash"] = payload_hash
        art["custom_headline_key"] = headline
        art["enriched"] = True
        art["link"] = art.get("link", f"{SITE_URL}/")
        art["source_quality"] = "full"
        art["source_type"] = "custom"
        art.setdefault("urgency_score", 6)
        art.setdefault("teaser", art.get("intro") or art.get("body", "")[:180].rstrip())
        if art.get("_custom_payload_unchanged"):
            stable_raw = (
                art.get("published_raw")
                or art.get("first_published")
                or art.get("date")
                or now.strftime("%a, %d %b %Y %H:%M:%S %z")
            )
            art["published_raw"] = stable_raw
            art["published"] = format_age(stable_raw) or stable_raw
        else:
            art.setdefault("published", now.strftime("%a, %d %b %Y %H:%M:%S %z"))
            art["published_raw"] = art.get("published_raw", art["published"])
            art["published"] = format_age(art["published_raw"]) or art["published_raw"]
        live.append(art)
    if live:
        print(f"  Custom articles loaded: {len(live)}")
    if skipped_published:
        print(f"  Custom queue retained {skipped_published} unchanged published item(s) as active placement(s)")
    if retired_skips:
        print(f"  Custom queue ignored {retired_skips} retired item(s)")
    return live

def load_archive(archive_path):
    try:
        if archive_path.exists():
            return json.loads(archive_path.read_text(encoding="utf-8"))
    except Exception:
        pass
    return []


