def _publication_slug_claim_diagnostics(item, entry):
    """Compare the immutable URL claim with the current headline/lead claim.

    A conservative automatic rebind requires both a jurisdiction change and a
    monetary-amount change. That catches the Port St. Lucie/$48 million article
    living under a St. Lucie County/$63 million URL without renaming ordinary
    stylistic headline updates.
    """
    item = item if isinstance(item, dict) else {}
    entry = entry if isinstance(entry, dict) else {}
    slug = str(entry.get("slug") or "")
    headline = str(item.get("headline") or item.get("title") or "")
    lead = _first_body_paragraph(
        item.get("body") or item.get("article_text") or item.get("teaser") or ""
    )
    headline_money = _extract_money_claims(headline)
    lead_money = _extract_money_claims(lead)
    current_money = headline_money & lead_money if headline_money and lead_money else headline_money or lead_money
    slug_money = _extract_money_claims(slug)
    headline_jurisdictions = _extract_jurisdiction_claims(headline)
    lead_jurisdictions = _extract_jurisdiction_claims(lead)
    current_jurisdictions = (
        headline_jurisdictions & lead_jurisdictions
        if headline_jurisdictions and lead_jurisdictions
        else headline_jurisdictions or lead_jurisdictions
    )
    slug_jurisdictions = _extract_jurisdiction_claims(slug)
    money_drift = bool(slug_money and current_money and slug_money.isdisjoint(current_money))
    jurisdiction_drift = bool(
        slug_jurisdictions
        and current_jurisdictions
        and slug_jurisdictions.isdisjoint(current_jurisdictions)
    )
    framing = _article_framing_diagnostics(item, item)
    return {
        "rebind_required": bool(
            framing.get("passed") and money_drift and jurisdiction_drift
        ),
        "framing_passed": bool(framing.get("passed")),
        "slug": slug,
        "headline": headline,
        "slug_money_claims": sorted(slug_money),
        "current_money_claims": sorted(current_money),
        "slug_jurisdictions": sorted(slug_jurisdictions),
        "current_jurisdictions": sorted(current_jurisdictions),
        "money_drift": money_drift,
        "jurisdiction_drift": jurisdiction_drift,
    }


def _claim_aligned_slug(item, entry, archive, today=None):
    headline = str((item or {}).get("headline") or "").strip()
    if not headline:
        return ""
    old_slug = str((entry or {}).get("slug") or "")
    date_match = re.match(r"^(20\d{2}-\d{2}-\d{2})-", old_slug)
    date_prefix = (
        date_match.group(1)
        if date_match
        else str((entry or {}).get("date") or today or datetime.utcnow().strftime("%Y-%m-%d"))[:10]
    )
    base = f"{date_prefix}-{slugify(headline)}"
    occupied = {
        str(row.get("slug") or "")
        for row in archive or []
        if row is not entry
    }
    candidate = base
    counter = 1
    while candidate in occupied:
        candidate = f"{base}-{counter}"
        counter += 1
    return candidate


def _rewrite_self_slug_in_article_html(html_text, old_slug, new_slug):
    value = str(html_text or "")
    old_path = f"/articles/{old_slug}.html"
    new_path = f"/articles/{new_slug}.html"
    value = value.replace(f"{SITE_URL}{old_path}", f"{SITE_URL}{new_path}")
    value = value.replace(old_path, new_path)
    return value


def _migrate_archive_entry_to_claim_aligned_slug(
    item, entry, archive, articles_dir, today=None, reason="primary_claim_slug_drift"
):
    diagnostics = _publication_slug_claim_diagnostics(item, entry)
    if not diagnostics.get("rebind_required"):
        return None
    old_slug = str(entry.get("slug") or "")
    new_slug = _claim_aligned_slug(item, entry, archive, today=today)
    if not old_slug or not new_slug or old_slug == new_slug:
        return None

    articles_dir = Path(articles_dir)
    old_path = articles_dir / f"{old_slug}.html"
    new_path = articles_dir / f"{new_slug}.html"
    if new_path.exists() and new_path != old_path:
        return None
    if old_path.exists():
        old_html = old_path.read_text(encoding="utf-8", errors="ignore")
        new_path.write_text(
            _rewrite_self_slug_in_article_html(old_html, old_slug, new_slug),
            encoding="utf-8",
        )
    old_headline = str(entry.get("headline") or item.get("headline") or "")
    entry["slug"] = new_slug
    entry["headline"] = str(item.get("headline") or entry.get("headline") or "")
    entry["teaser"] = str(item.get("teaser") or item.get("body", "")[:300] or entry.get("teaser") or "")
    entry["identity_origin"] = "claim_aligned_permalink_rebind"
    entry["legacy_identity_status"] = "identified"
    entry["ranking_eligible"] = True
    entry.pop("exclude_from_live_recovery", None)
    entry.pop("identity_quarantine_reason", None)

    redirect = {
        "source_slug": old_slug,
        "source_headline": old_headline,
        "target_slug": new_slug,
        "target_headline": entry.get("headline", ""),
        "story_stage": "claim-aligned-permalink-repair",
        "match_confidence": 100,
        "canonical_is_custom": False,
        "editorial_story_id": str(entry.get("editorial_story_id") or ""),
        "reason": reason,
        "claim_diagnostics": diagnostics,
    }
    articles_dir.mkdir(parents=True, exist_ok=True)
    old_path.write_text(
        _render_canonical_redirect_page(old_slug, new_slug, entry.get("headline", "")),
        encoding="utf-8",
    )
    return redirect


def _repair_archive_claim_drifted_permalinks(archive, articles_dir, output_root):
    """Repair historical URLs whose primary entity and amount no longer match copy."""
    repaired = []
    redirects = []
    for entry in list(archive or []):
        if entry.get("is_custom") or entry.get("authoritative_custom"):
            continue
        body = _archive_article_body(entry)
        if not body:
            continue
        item = {
            "headline": entry.get("headline", ""),
            "teaser": entry.get("teaser", ""),
            "body": body,
            "source_title": entry.get("source_headline", ""),
        }
        redirect = _migrate_archive_entry_to_claim_aligned_slug(
            item,
            entry,
            archive,
            articles_dir,
            today=str(entry.get("date") or "")[:10],
            reason="archive_primary_claim_slug_drift",
        )
        if not redirect:
            continue
        redirects.append(redirect)
        repaired.append({
            "source_slug": redirect["source_slug"],
            "target_slug": redirect["target_slug"],
            "headline": redirect["target_headline"],
            "claim_diagnostics": redirect.get("claim_diagnostics", {}),
        })

    report = {
        "schema_version": 1,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "policy": "rebind_only_when_jurisdiction_and_money_claim_both_drift",
        "repaired_count": len(repaired),
        "repaired": repaired,
    }
    report_path = Path(output_root) / "data" / "claim-aligned-permalink-repair.json"
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")
    if repaired:
        print(f"  Claim-aligned permalink repair migrated {len(repaired)} article URL(s)")
    return archive, redirects, report


def _repair_exact_headline_incident_duplicates(archive, articles_dir, output_root):
    """Collapse proven exact-headline incident duplicates before publication.

    This is a public-archive repair, not a fuzzy matcher. A group is changed only
    when every duplicate is within the bounded time window and independently agrees
    with the chosen canonical on locality, event family and an incident corroborator.
    """
    groups = defaultdict(list)
    for row in [entry for entry in (archive or []) if isinstance(entry, dict)]:
        if row.get("is_custom") or row.get("authoritative_custom"):
            continue
        if not _archive_entry_live_identity_safe(row):
            continue
        key = _normalized_generated_headline_key(row.get("headline"))
        if key and len(key.split()) >= 6:
            groups[key].append(row)

    removed = set()
    redirects = []
    repaired = []
    held = []
    for key, members in sorted(groups.items()):
        unique = {str(row.get("slug") or ""): row for row in members if row.get("slug")}
        if len(unique) < 2:
            continue
        ordered = sorted(unique.values(), key=_publication_canonical_key)
        canonical = ordered[0]
        decisions = []
        for duplicate in ordered[1:]:
            evidence = _exact_headline_incident_evidence(duplicate, canonical)
            decisions.append((duplicate, evidence))
        if not decisions or not all(evidence.get("write_authorized") for _, evidence in decisions):
            held.append({
                "headline_key": key,
                "slugs": [row.get("slug", "") for row in ordered],
                "reason": "exact_headline_group_not_fully_proven",
                "decisions": [
                    {
                        "slug": duplicate.get("slug", ""),
                        "reason": evidence.get("reason", ""),
                        "decision_trace": evidence.get("decision_trace", []),
                    }
                    for duplicate, evidence in decisions
                ],
            })
            continue

        for duplicate, evidence in decisions:
            source_slug = str(duplicate.get("slug") or "")
            target_slug = str(canonical.get("slug") or "")
            if not source_slug or not target_slug or source_slug == target_slug:
                continue
            removed.add(source_slug)
            _merge_category_memberships(
                canonical,
                duplicate,
                canonical.get("category_key") or duplicate.get("category_key") or "",
            )
            redirects.append({
                "source_slug": source_slug,
                "source_headline": duplicate.get("headline", ""),
                "target_slug": target_slug,
                "target_headline": canonical.get("headline", ""),
                "story_stage": "exact-final-headline-incident-reconciliation",
                "match_confidence": 99,
                "canonical_is_custom": False,
                "editorial_story_id": str(canonical.get("editorial_story_id") or ""),
                "reason": (
                    "Exact final headline plus locality, event family and incident-level "
                    "corroboration proved duplicate source coverage."
                ),
                "identity_evidence": evidence,
            })
            repaired.append({
                "source_slug": source_slug,
                "target_slug": target_slug,
                "headline": canonical.get("headline", ""),
                "source_story_id": duplicate.get("editorial_story_id", ""),
                "target_story_id": canonical.get("editorial_story_id", ""),
                "proof_type": evidence.get("proof_type", ""),
                "evidence_dimensions": evidence.get("evidence_dimensions", []),
            })

    cleaned = [row for row in (archive or []) if str(row.get("slug") or "") not in removed]
    report = {
        "schema_version": 1,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "release": "v1.12.0.8.4",
        "policy": "exact_final_headline_requires_locality_family_and_incident_corroboration",
        "repaired_count": len(repaired),
        "held_group_count": len(held),
        "repaired": repaired,
        "held_groups": held,
    }
    path = Path(output_root) / "data" / "exact-headline-incident-reconciliation.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
    if repaired:
        print(
            "  Exact-headline incident reconciliation consolidated "
            f"{len(repaired)} duplicate permalink(s)"
        )
    return cleaned, redirects, report


def _plain_article_paragraphs_from_html(html_text):
    match = re.search(
        r'(<div class="article-body">)(.*?)(</div>\s*(?:<aside class="newsletter-inline-slot[^>]*>.*?</aside>\s*)?<div class="article-share">)',
        str(html_text or ""),
        re.I | re.S,
    )
    if not match:
        return None, []
    import html as _html
    paragraphs = []
    for block in re.findall(r"<p(?:\s[^>]*)?>(.*?)</p>", match.group(2), re.I | re.S):
        plain = _html.unescape(re.sub(r"<[^>]+>", " ", block))
        plain = re.sub(r"\s+", " ", plain).strip()
        if plain:
            paragraphs.append(plain)
    return match, paragraphs


def _repair_archive_article_lead_framing(archive, articles_dir, output_root):
    """Promote an existing source-backed definition into a contextless first paragraph."""
    repairs = []
    articles_dir = Path(articles_dir)
    for entry in list(archive or []):
        if entry.get("is_custom") or entry.get("authoritative_custom"):
            continue
        slug = str(entry.get("slug") or "")
        path = articles_dir / f"{slug}.html"
        if not slug or not path.exists():
            continue
        html_text = path.read_text(encoding="utf-8", errors="ignore")
        if '<div class="article-body">' not in html_text or "<a " in html_text.split('<div class="article-body">', 1)[-1].split('<div class="article-share">', 1)[0]:
            continue
        match, paragraphs = _plain_article_paragraphs_from_html(html_text)
        if not match or len(paragraphs) < 2:
            continue
        item = {
            "headline": entry.get("headline", ""),
            "body": "\n\n".join(paragraphs),
            "source_title": entry.get("source_headline", ""),
        }
        diagnostics = _lead_independence_diagnostics(item, item)
        missing = list(diagnostics.get("missing") or [])
        if missing != ["named_measure_undefined_in_lead"]:
            continue
        undefined = diagnostics.get("undefined_references") or []
        definition_sentence = ""
        definition_paragraph_index = None
        for ref_text in undefined:
            ref = {"text": ref_text, "normalized": ref_text.casefold()}
            for paragraph_index, paragraph in enumerate(paragraphs[1:], start=1):
                for sentence in re.split(r"(?<=[.!?])\s+", paragraph):
                    sentence = sentence.strip()
                    if sentence and _lead_defines_policy_reference(sentence, ref):
                        definition_sentence = sentence
                        definition_paragraph_index = paragraph_index
                        break
                if definition_sentence:
                    break
            if definition_sentence:
                break
        if not definition_sentence or definition_paragraph_index is None:
            continue

        repaired_paragraphs = list(paragraphs)
        repaired_paragraphs[0] = (repaired_paragraphs[0].rstrip() + " " + definition_sentence).strip()
        remainder = repaired_paragraphs[definition_paragraph_index].replace(definition_sentence, "", 1).strip()
        remainder = re.sub(r"\s+", " ", remainder)
        if remainder:
            repaired_paragraphs[definition_paragraph_index] = remainder
        else:
            repaired_paragraphs.pop(definition_paragraph_index)
        repaired_item = dict(item)
        repaired_item["body"] = "\n\n".join(repaired_paragraphs)
        if not _lead_independence_diagnostics(repaired_item, repaired_item).get("passed"):
            continue

        body_html = "".join(f"<p>{html_lib.escape(paragraph)}</p>" for paragraph in repaired_paragraphs)
        new_html = html_text[:match.start(2)] + body_html + html_text[match.end(2):]
        path.write_text(new_html, encoding="utf-8")
        entry["teaser"] = repaired_paragraphs[0][:320]
        entry["article_word_count"] = _word_count(repaired_item["body"])
        entry["article_paragraph_count"] = len(repaired_paragraphs)
        entry["lead_integrity_repaired"] = True
        repairs.append({
            "slug": slug,
            "headline": entry.get("headline", ""),
            "definition_promoted": definition_sentence,
        })

    report = {
        "schema_version": 1,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "policy": "promote_existing_named_measure_definition_into_first_paragraph",
        "repaired_count": len(repairs),
        "repaired": repairs,
    }
    path = Path(output_root) / "data" / "archive-lead-framing-repair.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(report, indent=2), encoding="utf-8")
    if repairs:
        print(f"  Archive lead-framing repair updated {len(repairs)} article page(s)")
    return archive, report


def _redirect_target_path(slug):
    return f"/articles/{slug}.html"


def _render_canonical_redirect_page(source_slug, target_slug, target_headline=""):
    """Static-host-safe redirect fallback."""
    target_path = _redirect_target_path(target_slug)
    target_url = f"{SITE_URL}{target_path}"
    safe_title = re.sub(r"[<>]", "", target_headline or "Article moved")
    return f'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{safe_title} | {SITE_NAME}</title>
  <link rel="canonical" href="{target_url}">
  <meta name="robots" content="noindex,follow">
  <meta http-equiv="refresh" content="0; url={target_url}">
  <script>window.location.replace({json.dumps(target_url)});</script>
</head>
<body>
  <p>This article has moved to <a href="{target_url}">{safe_title}</a>.</p>
</body>
</html>'''


def _render_nonstory_redirect_page(headline=""):
    """Return a noindex redirect for a URL that was never a real article."""
    target_path = "/archive.html"
    target_url = f"{SITE_URL}{target_path}"
    safe_title = re.sub(r"[<>]", "", headline or "Treasure Coast Today archive")
    return f'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{safe_title} | {SITE_NAME}</title>
  <link rel="canonical" href="{target_url}">
  <meta name="robots" content="noindex,follow">
  <meta http-equiv="refresh" content="0; url={target_url}">
  <script>window.location.replace({json.dumps(target_url)});</script>
</head>
<body>
  <p>This page was not a published news article. Browse the <a href="{target_url}">Treasure Coast Today archive</a>.</p>
</body>
</html>'''


def _purge_nonstory_archive_entries(archive, articles_dir, output_root):
    """Remove synthetic status pages and preserve their URLs as noindex redirects."""
    articles_dir = Path(articles_dir)
    output_root = Path(output_root)
    kept = []
    removed = []
    for entry in list(archive or []):
        if _is_nonstory_placeholder(entry):
            removed.append({
                "slug": entry.get("slug", ""),
                "headline": entry.get("headline", ""),
                "category_key": entry.get("category_key", ""),
            })
            slug = entry.get("slug", "")
            if slug:
                articles_dir.mkdir(parents=True, exist_ok=True)
                (articles_dir / f"{slug}.html").write_text(
                    _render_nonstory_redirect_page(entry.get("headline", "")),
                    encoding="utf-8",
                )
            continue
        kept.append(entry)

    data_dir = output_root / "data"
    data_dir.mkdir(parents=True, exist_ok=True)
    report = {
        "schema_version": 1,
        "generated_at": datetime.utcnow().isoformat(timespec="seconds") + "Z",
        "removed_count": len(removed),
        "removed": removed,
    }
    (data_dir / "nonstory-purge.json").write_text(
        json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8"
    )
    if removed:
        print(f"  NONSTORY PURGE: removed {len(removed)} synthetic article record(s) from archive/RSS/sitemaps")
    return kept, report


def validate_nonstory_publication_contract(all_categories, top_cat, output_root):
    """Fail the deployment if section/status prose reaches any public surface."""
    output_root = Path(output_root)
    violations = []
    checked_live = 0

    placements = [("front_page", (top_cat or {}).get("hero") or {})]
    for category in all_categories or []:
        key = str(category.get("category_key") or "")
        placements.append((f"{key}:hero", category.get("hero") or {}))
        placements.extend((f"{key}:card", card) for card in category.get("cards") or [])
    for surface, item in placements:
        if not item:
            continue
        checked_live += 1
        if _is_nonstory_placeholder(item):
            violations.append({"surface": surface, "headline": item.get("headline", "")})

    archive = load_archive(output_root / "archive.json")
    for entry in archive:
        if _is_nonstory_placeholder(entry):
            violations.append({
                "surface": "archive",
                "headline": entry.get("headline", ""),
                "slug": entry.get("slug", ""),
            })

    # RSS is checked independently so a future refactor cannot bypass the object gate.
    rss_path = output_root / "feed.xml"
    rss_titles = []
    if rss_path.exists():
        rss_text = rss_path.read_text(encoding="utf-8", errors="ignore")
        rss_titles = re.findall(r"<title><!\[CDATA\[(.*?)\]\]></title>", rss_text, re.DOTALL)
        custom_titles = {
            _normalize_nonstory_text(e.get("headline", ""))
            for e in archive if e.get("is_custom") or e.get("authoritative_custom")
        }
        for title in rss_titles:
            probe = {"headline": title}
            if _normalize_nonstory_text(title) in custom_titles:
                probe["is_custom"] = True
            if _is_nonstory_placeholder(probe):
                violations.append({"surface": "rss", "headline": title})

    report = {
        "schema_version": 1,
        "generated_at": datetime.utcnow().isoformat(timespec="seconds") + "Z",
        "status": "failed" if violations else "passed",
        "passed": not violations,
        "checked_live_placements": checked_live,
        "checked_archive_entries": len(archive),
        "checked_rss_items": len(rss_titles),
        "violation_count": len(violations),
        "violations": violations,
    }
    data_dir = output_root / "data"
    data_dir.mkdir(parents=True, exist_ok=True)
    (data_dir / "nonstory-publication-contract.json").write_text(
        json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8"
    )
    if violations:
        raise RuntimeError(
            "Nonstory publication contract FAILED: "
            + "; ".join(v.get("headline", "") for v in violations[:5])
        )
    print(
        "  Nonstory publication contract PASSED "
        f"({checked_live} live placement(s), {len(archive)} archive record(s), "
        f"{len(rss_titles)} RSS item(s))"
    )
    return report


def _resolve_custom_publication_target(hero, archive, existing, headline):
    """Authorize custom updates only through immutable exact-headline identity.

    A new custom headline may never reuse an archive slug already owned by another
    article. This fails closed whether the collision came from a queue editing error,
    a persistent-story false match, or a stale live/archive clone.
    """
    if not (hero.get("is_custom") or hero.get("authoritative_custom")):
        return existing, None, None
    headline_key = _exact_custom_headline(headline)
    matches = [
        entry for entry in archive or []
        if isinstance(entry, dict)
        and (entry.get("is_custom") or entry.get("authoritative_custom"))
        and not entry.get("retired_custom")
        and _archive_custom_headline_key(entry) == headline_key
    ]
    matches.sort(key=lambda row: (
        str(row.get("first_published") or row.get("date") or ""),
        str(row.get("slug") or ""),
    ))
    target = matches[0] if matches else None
    if target is not None:
        story_id = str(target.get("editorial_story_id") or "").strip()
        if not story_id:
            story_id = "custom:" + hashlib.sha256(
                ("headline|" + headline_key).encode("utf-8")
            ).hexdigest()[:32]
        return target, None, story_id

    # Preserve a diagnostic marker when a live/archive clone brought an older
    # custom permalink into a differently titled submission. The stale slug is
    # quarantined, not reused; the different headline receives a new identity.
    if "_custom_requested_slug" not in hero and isinstance(existing, dict):
        inherited_slug = _normalize_custom_slug(hero.get("slug"))
        existing_slug = _normalize_custom_slug(existing.get("slug"))
        if inherited_slug and inherited_slug == existing_slug:
            hero["_superseded_custom_slug"] = existing_slug
            hero["_custom_series_permalink_repair"] = True

    # Only a slug explicitly captured from custom_articles.json may choose a
    # new custom permalink. ``hero["slug"]`` can be inherited from a stale
    # archive/live placement and must never authorize reuse when the exact
    # headline does not match.
    requested_slug = hero.get("_custom_requested_slug", "")
    forced_slug = _validated_custom_requested_slug(requested_slug) or None
    if forced_slug:
        collision = next(
            (
                entry for entry in archive or []
                if _normalize_custom_slug(entry.get("slug")) == forced_slug
                and _archive_custom_headline_key(entry) != headline_key
            ),
            None,
        )
        if collision is not None:
            raise RuntimeError(
                "Custom publication slug collision: "
                f"'{headline_key}' requested '{forced_slug}', but that permalink "
                f"already belongs to '{collision.get('headline', '')}'. "
                "Use a new unique slug; generation stopped before any article page "
                "could be overwritten."
            )

    story_id = "custom:" + hashlib.sha256(
        ("headline|" + headline_key).encode("utf-8")
    ).hexdigest()[:32]
    return None, forced_slug, story_id

def _publication_copy_rank(entry):
    """Rank competing generated copies for one public story.

    Manually authored custom copy is absolute editorial authority. It outranks hero
    placement, images, body length, and every generated/feed version so coalescing can
    never replace the submitted body while leaving only its headline on cards.
    """
    _ck, _cl, item = entry
    is_custom = 1 if item.get("is_custom") or item.get("authoritative_custom") else 0
    active_custom_payload = 1 if is_custom and not item.get("_archive_only") else 0
    has_real_img = 1 if (item.get("image_url") and not item.get("image_from_google")) else 0
    is_hero_copy = 1 if item.get("_is_hero_copy") else 0
    body_words = _word_count(item.get("body", ""))
    # A current queue payload must outrank an archive-recovery clone, even when the
    # clone is currently a hero. Otherwise the clone wins coalescing and is then
    # silently skipped by the archive-only guard before the custom permalink exists.
    return (is_custom, active_custom_payload, has_real_img, is_hero_copy, body_words)



def _publication_coalesce_key(item, identity_index=None):
    """Use exact custom headlines and persistent generated-story IDs."""
    if not isinstance(item, dict):
        return ""
    if item.get("is_custom") or item.get("authoritative_custom"):
        headline = _exact_custom_headline(item.get("headline"))
        return (
            "custom-headline:" + hashlib.sha256(headline.encode("utf-8")).hexdigest()
            if headline else ""
        )
    incident_anchor = _durable_incident_anchor(item)
    if incident_anchor:
        return f"incident-anchor:{incident_anchor}"
    story_id = _publication_story_id(item, identity_index)
    if story_id:
        item["_editorial_story_id"] = story_id
        return f"editorial-story:{story_id}"
    headline_key = re.sub(r"[^a-z0-9 ]", "", str(item.get("headline") or "").lower()).strip()[:60]
    return f"headline:{headline_key}" if headline_key else ""


CANONICAL_PUBLICATION_LEDGER_VERSION = "1.1"


def _stable_publication_id(slug):
    slug = str(slug or "").strip()
    if not slug:
        return ""
    return "publication:" + hashlib.sha256(slug.encode("utf-8")).hexdigest()[:24]


def _ensure_publication_identity_fields(entry, canonical_slug=""):
    if not isinstance(entry, dict):
        return entry
    slug = str(entry.get("slug") or entry.get("_archived_slug") or "").strip()
    if not slug:
        return entry
    publication_id = str(entry.get("publication_id") or "").strip() or _stable_publication_id(slug)
    canonical_slug = str(canonical_slug or entry.get("canonical_slug") or slug).strip()
    canonical_publication_id = (
        str(entry.get("canonical_publication_id") or "").strip()
        if canonical_slug == slug
        else ""
    ) or _stable_publication_id(canonical_slug)
    entry["publication_id"] = publication_id
    entry["canonical_slug"] = canonical_slug
    entry["canonical_publication_id"] = canonical_publication_id
    return entry


def _publication_ledger_identity_keys(item, identity_index=None, *, include_archive_body=False):
    """Return deterministic identities that may own one canonical TCT permalink.

    Exact source identity, the persistent story ID and structured incident identity
    are independent evidence channels. The publication writer may use any one of them
    to find an existing canonical, but historical auto-redirects use only safe story
    IDs or independently structured incident/source identity.
    """
    if not isinstance(item, dict):
        return ()
    keys = []
    stored_identity = item.get("event_identity") if isinstance(item, dict) else None
    anchor = str(
        (stored_identity or {}).get("incident_anchor")
        if isinstance(stored_identity, dict)
        else ""
    ).strip()
    if not anchor:
        anchor = str(item.get("incident_anchor_key") or "").strip()
    if not anchor:
        try:
            anchor = str(
                _event_identity_snapshot(
                    item, include_archive_body=include_archive_body
                ).get("incident_anchor")
                or ""
            ).strip()
        except Exception:
            anchor = ""
    if anchor:
        keys.append(f"incident:{anchor}")

    story_id = str(
        item.get("editorial_story_id")
        or item.get("_editorial_story_id")
        or ""
    ).strip()
    if not story_id and identity_index is not None:
        try:
            story_id = str(identity_index.resolve(item) or "").strip()
        except Exception:
            story_id = ""
    if story_id:
        keys.append(f"story:{story_id}")

    source_url = _normalized_external_source_url(
        item.get("source_url")
        or item.get("_source_url")
        or item.get("original_url")
        or item.get("link")
        or item.get("url")
    )
    if source_url:
        rolling = bool(
            source_identity_requires_title_continuity is not None
            and source_identity_requires_title_continuity(
                source_url,
                title=(
                    item.get("source_headline")
                    or item.get("headline")
                    or item.get("title")
                    or ""
                ),
            )
        )
        # A rolling weather/traffic/live URL is a source slot, not one immutable
        # event. It may retrieve candidates elsewhere, but cannot own a canonical
        # ledger key or independently authorize an overwrite.
        if not rolling:
            keys.append(f"source:{source_url}")

    custom_event = str(
        item.get("custom_event_key")
        or item.get("durable_custom_identity_key")
        or ""
    ).strip()
    if custom_event:
        keys.append(f"custom-event:{custom_event}")

    weather_event = str(item.get("weather_event_key") or "").strip()
    if weather_event:
        keys.append(f"weather:{weather_event}")
    return tuple(dict.fromkeys(keys))


def _publication_ledger_candidate_safe(entry):
    if not isinstance(entry, dict) or not entry.get("slug"):
        return False
    if _is_nonstory_placeholder(entry):
        return False
    if _archive_entry_live_identity_safe(entry):
        return True
    reason = str(entry.get("identity_quarantine_reason") or "")
    # This quarantine was created by treating a changed headline as a changed story.
    # A canonical publication ledger must be able to repair that exact failure.
    return reason.startswith("prospective_headline_slug_event_drift")


def _repair_false_permalink_quarantine(entry, *, reason="canonical_publication_ledger"):
    if not isinstance(entry, dict):
        return False
    quarantine = str(entry.get("identity_quarantine_reason") or "")
    if not quarantine.startswith("prospective_headline_slug_event_drift"):
        return False
    entry.pop("exclude_from_live_recovery", None)
    entry.pop("identity_quarantine_reason", None)
    entry["legacy_identity_status"] = "identified"
    entry["ranking_eligible"] = True
    entry["identity_origin"] = reason
    return True



